window.__RECU={"k": "bol-van/zapret-win-bundle", "g": "diagrammes", "t": "```mermaid\nflowchart TD\n\nsubgraph group_runtime[\"Live bypass runtime\"]\n  node_win_traffic((\"Windows traffic<br/>network traffic\"))\n  node_windivert_driver[(\"WinDivert<br/>kernel driver<br/>[WinDivert64.sys]\")]\n  node_winws_engine[\"winws<br/>user-space engine<br/>[winws.exe]\"]\n  node_winws2_engine[\"winws2<br/>user-space engine<br/>[winws2.exe]\"]\nend\n\nsubgraph group_presets[\"Launchers and services\"]\n  node_zapret1_presets[\"zapret1 presets<br/>cmd launchers\"]\n  node_zapret2_presets[\"zapret2 presets<br/>cmd launchers\"]\n  node_service_scripts[\"Service mode<br/>cmd service control<br/>[service_create.cmd]\"]\nend\n\nsubgraph group_policy[\"Policy assets\"]\n  node_lua_rules1[\"Lua policy<br/>rule scripts<br/>[zapret-antidpi.lua]\"]\n  node_lua_rules2[\"Lua policy 2<br/>rule scripts<br/>[zapret-antidpi.lua]\"]\n  node_fake_payloads1[\"Fake payloads<br/>binary decoys\"]\n  node_fake_payloads2[\"Fake payloads 2<br/>binary decoys\"]\nend\n\nsubgraph group_diagnostics[\"Blockcheck\"]\n  node_blockcheck1[\"Blockcheck<br/>probe harness<br/>[blockcheck.sh]\"]\n  node_blockcheck2[\"Blockcheck2<br/>probe harness<br/>[blockcheck2.sh]\"]\n  node_standard_tests[\"Test suites<br/>sh test cases<br/>[10-http-basic.sh]\"]\n  node_custom_tests[\"Custom lists<br/>test lists<br/>[list_http.txt]\"]\nend\n\nsubgraph group_portability[\"Windows support\"]\n  node_cygwin_runtime[\"Cygwin<br/>windows shell layer<br/>[bash.exe]\"]\n  node_elevation_tools[\"Elevators<br/>privilege helpers<br/>[elevator.exe]\"]\n  node_platform_bundles[(\"Platform bundles<br/>platform support<br/>[WinDivert64.sys]\")]\n  node_hide_tools[(\"Hide tools<br/>driver utilities<br/>[Monkey64.sys]\")]\nend\n\nnode_win_traffic -->|\"captures\"| node_windivert_driver\nnode_windivert_driver -->|\"feeds\"| node_winws_engine\nnode_windivert_driver -->|\"feeds\"| node_winws2_engine\nnode_winws_engine -->|\"reinjects\"| node_win_traffic\nnode_winws2_engine -->|\"reinjects\"| node_win_traffic\nnode_zapret1_presets -->|\"launches\"| node_winws_engine\nnode_zapret2_presets -->|\"launches\"| node_winws2_engine\nnode_service_scripts -->|\"starts\"| node_winws_engine\nnode_service_scripts -->|\"starts\"| node_winws2_engine\nnode_lua_rules1 -->|\"configures\"| node_winws_engine\nnode_lua_rules2 -->|\"configures\"| node_winws2_engine\nnode_fake_payloads1 -->|\"supplies decoys\"| node_winws_engine\nnode_fake_payloads2 -->|\"supplies decoys\"| node_winws2_engine\nnode_blockcheck1 -.->|\"evaluates\"| node_lua_rules1\nnode_blockcheck2 -.->|\"evaluates\"| node_lua_rules2\nnode_standard_tests -.->|\"drives\"| node_blockcheck2\nnode_custom_tests -.->|\"drives\"| node_blockcheck2\nnode_cygwin_runtime -->|\"runs\"| node_blockcheck1\nnode_cygwin_runtime -->|\"runs\"| node_blockcheck2\nnode_elevation_tools -->|\"enables\"| node_service_scripts\nnode_platform_bundles -->|\"packages\"| node_windivert_driver\nnode_hide_tools -->|\"manages\"| node_windivert_driver\nnode_blockcheck1 -.->|\"profiles\"| node_winws_engine\nnode_blockcheck2 -.->|\"profiles\"| node_winws2_engine\n\nclick node_windivert_driver \"https://github.com/bol-van/zapret-win-bundle/blob/master/zapret-winws/WinDivert64.sys\"\nclick node_winws_engine \"https://github.com/bol-van/zapret-win-bundle/blob/master/zapret-winws/winws.exe\"\nclick node_winws2_engine \"https://github.com/bol-van/zapret-win-bundle/blob/master/zapret-winws/winws2.exe\"\nclick node_zapret1_presets \"https://github.com/bol-van/zapret-win-bundle/blob/master/zapret-winws/preset1_example.cmd\"\nclick node_zapret2_presets \"https://github.com/bol-van/zapret-win-bundle/blob/master/zapret-winws/preset2_example.cmd\"\nclick node_service_scripts \"https://github.com/bol-van/zapret-win-bundle/blob/master/zapret-winws/service_create.cmd\"\nclick node_lua_rules1 \"https://github.com/bol-van/zapret-win-bundle/blob/master/zapret-winws/lua/zapret-antidpi.lua\"\nclick node_lua_rules2 \"https://github.com/bol-van/zapret-win-bundle/blob/master/blockcheck/zapret2/lua/zapret-antidpi.lua\"\nclick node_fake_payloads1 \"https://github.com/bol-van/zapret-win-bundle/blob/master/zapret-winws/files/quic_initial_www_google_com.bin\"\nclick node_fake_payloads2 \"https://github.com/bol-van/zapret-win-bundle/blob/master/blockcheck/zapret/files/fake/tls_clienthello_www_google_com.bin\"\nclick node_blockcheck1 \"https://github.com/bol-van/zapret-win-bundle/blob/master/blockcheck/zapret/blockcheck.sh\"\nclick node_blockcheck2 \"https://github.com/bol-van/zapret-win-bundle/blob/master/blockcheck/zapret2/blockcheck2.sh\"\nclick node_standard_tests \"https://github.com/bol-van/zapret-win-bundle/blob/master/blockcheck/zapret2/blockcheck2.d/standard/10-http-basic.sh\"\nclick node_custom_tests \"https://github.com/bol-van/zapret-win-bundle/blob/master/blockcheck/zapret2/blockcheck2.d/custom/list_http.txt\"\nclick node_cygwin_runtime \"https://github.com/bol-van/zapret-win-bundle/blob/master/cygwin/bin/bash.exe\"\nclick node_elevation_tools \"https://github.com/bol-van/zapret-win-bundle/blob/master/tools/elevator.exe\"\nclick node_platform_bundles \"https://github.com/bol-van/zapret-win-bundle/blob/master/arm64/WinDivert64.sys\"\nclick node_hide_tools \"https://github.com/bol-van/zapret-win-bundle/blob/master/windivert-hide/Monkey64.sys\"\n\nclassDef toneNeutral fill:#f8fafc,stroke:#334155,stroke-width:1.5px,color:#0f172a\nclassDef toneBlue fill:#dbeafe,stroke:#2563eb,stroke-width:1.5px,color:#172554\nclassDef toneAmber fill:#fef3c7,stroke:#d97706,stroke-width:1.5px,color:#78350f\nclassDef toneMint fill:#dcfce7,stroke:#16a34a,stroke-width:1.5px,color:#14532d\nclassDef toneRose fill:#ffe4e6,stroke:#e11d48,stroke-width:1.5px,color:#881337\nclassDef toneIndigo fill:#e0e7ff,stroke:#4f46e5,stroke-width:1.5px,color:#312e81\nclassDef toneTeal fill:#ccfbf1,stroke:#0f766e,stroke-width:1.5px,color:#134e4a\nclass node_win_traffic,node_windivert_driver,node_winws_engine,node_winws2_engine toneBlue\nclass node_zapret1_presets,node_zapret2_presets,node_service_scripts toneAmber\nclass node_lua_rules1,node_lua_rules2,node_fake_payloads1,node_fake_payloads2 toneMint\nclass node_blockcheck1,node_blockcheck2,node_standard_tests,node_custom_tests toneRose\nclass node_cygwin_runtime,node_elevation_tools,node_platform_bundles,node_hide_tools toneIndigo\n```\n\nThis repository is a Windows deployment bundle for the zapret / zapret2 DPI-bypass tools. It is not a typical application codebase; it is mostly packaged binaries, batch launchers, shell scripts, and support files that assemble a user-mode traffic manipulator around the WinDivert driver.\n\n1. Core runtime boundary  \nThe central architectural boundary is between the Windows kernel and user space. WinDivert (`WinDivert64.sys`) captures and reinjects network packets, while `winws.exe` and `winws2.exe` run in user space and decide how to transform traffic to evade DPI.\n\n2. Two parallel engines: zapret1 and zapret2  \nThe repo ships two generations of the bypass engine:\n- `zapret-winws/` for the first engine, centered on `winws.exe`\n- `zapret-winws/` plus `blockcheck/zapret2/` for the second engine, centered on `winws2.exe`\nBoth are packaged separately because they use different Lua logic, presets, and blockcheck flows.\n\n3. Traffic-processing pipeline  \nThe main data flow is:\nWindows network traffic -> WinDivert driver -> `winws` / `winws2` -> packet mangling rules -> reinjection onto the network.  \nThe engine can rewrite, split, fake, or reorder packets depending on the chosen strategy, especially for TLS, QUIC, WireGuard, STUN, Discord media, and DHT traffic.\n\n4. Rule logic and protocol knowledge in Lua  \nThe `lua/` directory is the policy layer. Scripts such as `zapret-antidpi.lua`, `zapret-auto.lua`, `zapret-obfs.lua`, and `zapret-tests.lua` contain the traffic classification and obfuscation behavior. This is the main place where protocol-specific bypass strategies live.\n\n5. Embedded fake traffic payloads  \nThe `files/fake/` directories contain binary packet templates used as decoys or crafted protocol fragments. These include TLS ClientHello variants, QUIC initial packets, WireGuard initiation/response, STUN, DTLS, HTTP, and zero-filled blobs. They are part of the bypass mechanism, not sample data.\n\n6. Strategy presets and interactive launchers  \nFiles like `preset1_example.cmd`, `preset2_example.cmd`, and `preset2_wireguard.cmd` are launch entry points for specific bypass strategies. They sit above the engines and assemble the command-line arguments, filters, and options for a chosen scenario.\n\n7. Service mode vs interactive mode  \nThe `service*.cmd` scripts create and control Windows services for non-interactive startup, while the preset `.cmd` files are intended for manual, interactive runs. This is an important operational boundary: the same engine can run either as a foreground tool or as an autostart service.\n\n8. Blockcheck subsystem for strategy discovery  \n`blockcheck/` and `blockcheck2/` are analysis toolchains used to detect what kind of DPI interference exists and which bypass method works. They are separate from the runtime bypass path and should be thought of as a diagnostics/probing subsystem.\n\n9. Probing and test harnesses  \nBlockcheck uses shell scripts plus bundled tools like `curl`, `mdig.exe`, and `ip2net.exe` to generate and observe traffic patterns against target services. The `blockcheck2.d/standard` and `custom` directories define test suites for HTTP, TLS 1.2/1.3, QUIC, and other protocols.\n\n10. Windows portability layers  \nThe repo includes a minimal `cygwin/` tree so the shell-based tooling can run on Windows. It also includes admin/elevation helpers such as `elevator.exe` and `cygwin-admin.cmd`, because many operations require administrator privileges to load the driver and manipulate traffic.\n\n11. Platform-specific bundles  \nThere are separate platform support folders:\n- `arm64/` for Windows 11+ ARM64\n- `win7/` for older Windows 7 / Server 2008 R2 compatibility\n- `windivert-hide/` for driver-related hiding/removal utilities  \nThese folders reflect deployment constraints rather than separate products.\n\n12. Operational dependencies and constraints  \nThe architecture depends on:\n- Windows x64 / ARM64 support\n- WinDivert kernel driver\n- elevated privileges\n- sometimes testsigning mode or secure boot adjustments\n- the Windows networking stack and, for some scenarios, service installation  \nThe README’s antivirus warning matters because the driver-hooking model is behaviorally similar to security-sensitive software.\n\n13. Overall architectural shape  \nAt a high level, this repo is a packaged DPI-bypass platform with three layers:\n- capture layer: WinDivert driver\n- decision/action layer: `winws` / `winws2` plus Lua and fake-packet assets\n- orchestration/diagnostics layer: batch scripts, Cygwin shell scripts, blockcheck, and service installers  \nThe key diagram should show these layers explicitly, with blockcheck separated from the live packet modification path.\n\n> Diagramme produit par **GitDiagram** à partir du code du dépôt, le 2026-05-15."};